/**
 * EventWorkspacesChanged announces that a workspace, a membership or a hold mark changed.
 */
export const EventWorkspacesChanged = "workspaces-changed";
/**
 * ProjectWorktrees is one project in the /v1/projects/worktrees payload: its
 * repo root, the dirs of its other worktrees and the model each tier runs under
 * for the chat harness (empty when that tier inherits the CLI's own setting).
 */
export interface ProjectWorktrees {
  project: string;
  root: string;
  worktrees: string[];
  tiers: { [key: string]: string};
  /**
   * TierModels holds configured models by harness and tier.
   */
  tier_models?: { [key: string]: { [key: string]: string}};
}
/**
 * Tip is one entry of the tips page. Folders is filled by the call for tips
 * that point at the project worktree folders.
 */
export interface Tip {
  id: string;
  title: string;
  body: string;
  platform: string; // GOOS value the tip applies to
  folders?: string[];
}
/**
 * Workspace is one workspace as the list and the snapshot show it.
 */
export interface Workspace {
  name: string;
  default?: boolean;
  members: number /* int */;
  /**
   * NeedsYou counts the workspace's Needs-you cards; filled in by the server, 0 when none.
   */
  needs_you?: number /* int */;
  /**
   * Sort is one of the Sort* values.
   */
  sort?: string;
}
/**
 * WorkspaceList is the workspaces in order.
 */
export interface WorkspaceList {
  workspaces: Workspace[];
}
/**
 * WorkspaceRequest is a workspace write: Name is the workspace acted on, To the
 * new name of a rename. Key is the Design, epic or chat a move or remove acts
 * on (a remove; Name is the target workspace of a move); Targets are the keys a move acts on;
 * Order is the full new order of a reorder.
 * Sort is the Sort* value a sort write sets on Name.
 */
export interface WorkspaceRequest {
  name: string;
  to?: string;
  key?: string;
  targets?: string[];
  order?: string[];
  sort?: string;
}
export const PlacementChat = "chat";
export const PlacementEpic = "epic";
export const PlacementOther = "other";
/**
 * Where a session sits in the sidebar.
 */
export type Placement = typeof PlacementChat | typeof PlacementEpic | typeof PlacementOther;
/**
 * SessionPlacement says where one session sits: a chat (with its workspace
 * name), under an epic (that epic's address), or in Other.
 */
export interface SessionPlacement {
  session: string;
  kind: string;
  workspace?: string;
  epic?: string;
}
/**
 * WorkspaceResult is a workspace write: the list after it, or a refusal.
 */
export interface WorkspaceResult {
  workspaces?: Workspace[];
  refused?: boolean;
  reason?: string;
  message?: string;
}
/**
 * HoldRequest holds or unholds Designs or epics. Yes confirms, for the whole
 * request, that holding exits a Design's live sessions. DryRun runs every rule
 * and writes nothing.
 */
export interface HoldRequest {
  targets: string[];
  yes?: boolean;
  dry_run?: boolean;
}
/**
 * Refusal reasons of hold. The queued text is asserted by the web.
 */
export const ReasonHoldQueued = "hold-queued";
/**
 * Refusal reasons of hold. The queued text is asserted by the web.
 */
export const ReasonHoldNotHoldable = "hold-not-holdable";
/**
 * Refusal reasons of hold. The queued text is asserted by the web.
 */
export const ReasonHoldUnknown = "hold-unknown";
/**
 * Refusal reasons of hold. The queued text is asserted by the web.
 */
export const ReasonNotOnHold = "not-on-hold";
/**
 * Refusal reasons of hold. The queued text is asserted by the web.
 */
export const HoldQueuedText = "Remove it from the queue first";
export const ReasonWorkspaceBlankName = "workspace-blank-name";
export const ReasonWorkspaceNameTaken = "workspace-name-taken";
export const ReasonWorkspaceUnknown = "workspace-unknown";
export const ReasonWorkspaceDefaultFixed = "workspace-default-fixed";
export const ReasonWorkspaceBadOrder = "workspace-bad-order";
export const ReasonWorkspaceBlankKey = "workspace-blank-key";
export const ReasonWorkspaceUnknownKey = "workspace-unknown-key";
export const ReasonWorkspaceFollowsEpic = "workspace-follows-epic";
export const ReasonWorkspaceNotJoinable = "workspace-not-joinable";
export const ReasonWorkspaceBadSort = "workspace-bad-sort";
/**
 * Refusal reasons of the workspace writes.
 */
export type ReasonWorkspace = typeof ReasonWorkspaceBlankName | typeof ReasonWorkspaceNameTaken | typeof ReasonWorkspaceUnknown | typeof ReasonWorkspaceDefaultFixed | typeof ReasonWorkspaceBadOrder | typeof ReasonWorkspaceBlankKey | typeof ReasonWorkspaceUnknownKey | typeof ReasonWorkspaceFollowsEpic | typeof ReasonWorkspaceNotJoinable | typeof ReasonWorkspaceBadSort;
export const SortNeedsYou = "needs-you";
export const SortActivity = "activity";
export const SortName = "name";
export const SortProject = "project";
export const SortStatus = "status";
/**
 * Sort values of a workspace. The labels live in the web.
 */
export type Sort = typeof SortNeedsYou | typeof SortActivity | typeof SortName | typeof SortProject | typeof SortStatus;
/**
 * SortDefault is what a workspace reads as until a Sort is set.
 */
export const SortDefault = SortNeedsYou;
